const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Number.isFinite(v)?v.toLocaleString('ru-RU',{maximumFractionDigits:1}):'—';
const avg=a=>{const xs=a.filter(Number.isFinite);return xs.length?xs.reduce((s,v)=>s+v,0)/xs.length:null;};
const priorities={1:'фарм, урон героям и давление на строения',2:'темп получения опыта и урон героям',3:'урон и помощь в убийствах',4:'помощь команде, опыт и урон',5:'помощь команде, опыт и доступные показатели лечения',support:'помощь команде и участие в действиях союзников',core:'экономика и урон',unknown:'общий набор доступных показателей'};
export function hasContribution(r){return Number.isFinite(r.sourceComparison?.mean)&&r.sourceComparison.count>0;}
export function verdictExplanationHTML(r){
 const games=r.matches||[],scored=games.filter(m=>Number.isFinite(m.score)),wins=scored.filter(m=>m.win===true),losses=scored.filter(m=>m.win===false),strong=scored.filter(m=>m.score>=65),weak=scored.filter(m=>m.score<40);
 const groups=r.roleSummary||[],unknown=groups.find(g=>g.key==='unknown')?.games||0;
 const metricText=xs=>xs.map(x=>`${esc(x.label)} — ${num(x.percentile)}/100 (игр с данными: ${x.samples})`).join('; ');
 const metrics=(r.comparisons||[]).filter(x=>Number.isFinite(x.percentile)&&x.samples>0),high=metrics.filter(x=>x.percentile>=60).sort((a,b)=>b.percentile-a.percentile).slice(0,3),low=metrics.filter(x=>x.percentile<40).sort((a,b)=>a.percentile-b.percentile).slice(0,3);
 const outcome=(xs,label)=>xs.length?`<p><b>${label}: ${xs.length}.</b> Средняя оценка игры — ${num(avg(xs.map(m=>m.score)))}/100. Сильных по показателям игр: ${xs.filter(m=>m.score>=65).length}; слабых: ${xs.filter(m=>m.score<40).length}. Средние убийства / смерти / помощь — ${['kills','deaths','assists'].map(k=>num(avg(xs.map(m=>m.player?.[k])))).join(' / ')}; золото в минуту — ${num(avg(xs.map(m=>m.player?.gold_per_min)))}. Эти средние описывают данную часть серии; различия героев, ролей и длительности могут влиять на них.</p>`:`<p><b>${label}:</b> оценённых игр с таким исходом нет.</p>`;
 const costly=games.filter(m=>(m.fights||[]).some(f=>f.deaths>0&&f.goldDelta<0)).length,parsed=games.filter(m=>m.parsed||m.stratz?.parsedAt).length;
 return `<div class="verdict-explanation"><p><b>${esc(r.profile?.personaname||'Игрок')}: «${esc(r.verdict)}».</b> ${esc(plainSummary(r))}</p>
 <div class="explanation-columns"><section><h3>Роли и задачи игрока</h3>${groups.map(g=>`<p><b>${esc(g.role)} — ${g.games} игр, оценка ${num(g.score)}/100.</b> В оценке важны ${priorities[g.key]||priorities.unknown}. ${['4','5','support'].includes(g.key)?'Низкий фарм сам по себе не снижает оценку поддержки.':''}</p>`).join('')||'<p>Пока нет игр с достаточными данными для оценки роли.</p>'}${unknown?`<p class="muted">В ${unknown} играх роль не определена: применены общие веса. Поэтому вывод о выполнении конкретной позиции для этих игр ограничен.</p>`:''}</section><section><h3>Что отличает победы и поражения</h3>${outcome(wins,'Победы')}${outcome(losses,'Поражения')}<p class="muted">Слабые показатели в проигранной игре не доказывают, что именно этот игрок стал причиной поражения. Сильная личная статистика также не гарантирует победу команды.</p></section></div>
 <h3>Какие показатели поддерживают вывод</h3><p>${high.length?`Выше середины распределения по героям: <b>${metricText(high)}</b>.`:'Устойчиво высоких средних процентилей (от 60/100) по доступным показателям не обнаружено.'} ${low.length?`Ниже ориентиров: <b>${metricText(low)}</b>.`:'Средних процентилей ниже 40/100 в доступном наборе нет.'} Процентиль показывает положение относительно других наблюдений на том же герое, а не процент эффективности. К показателям по герою добавлены участие в действиях команды, соотношение урона и полученных ресурсов, а также частота смертей с учётом длительности и роли. При длительном сильном отставании команды вес обычных ориентиров уменьшается. Важность каждого показателя меняется с ролью; отсутствующие значения не заменяются нулями.</p>
 <p>${r.cohortComparison?.matchedGames?`Дополнительно сопоставлены ${r.cohortComparison.matchedGames} игр с группой «${esc(r.cohortComparison.group)}» на тех же героях и позициях, на близкой минуте игры. Конкретные средние и разница показаны ниже в статистике серии. Эта сверка пока не входит в итоговую оценку.`:'Сопоставимых средних одновременно по рейтинговой группе, герою и позиции пока недостаточно. Поэтому здесь не заявляется точное сравнение с игроками того же рейтинга.'}</p>
 <h3>Что удалось проверить в реплеях</h3><p>Подробные данные доступны для ${parsed} из ${games.length} игр. ${costly?`В ${costly} играх есть драки, где игрок погиб и потерял золото; эти эпизоды доступны для проверки в разборах.`:'Повторяющиеся смерти с потерей золота в доступных событиях не выявлены.'} Покупки, позиции на линии, обзор и события драк дополняют картину, но не все они входят в итоговую оценку. ${hasContribution(r)?`Дополнительная оценка вклада доступна для ${r.sourceComparison.count} игр, среднее — ${num(r.sourceComparison.mean)}. ${r.sourceComparison.disagreement?'Она расходится с основной оценкой, что учтено в осторожном итоговом вердикте.':'Она служит отдельной сверкой личных показателей.'}`:''}</p><p class="muted">Вывод формирует система правил и весов по доступным данным. Это объяснение расчёта, а не просмотр всех решений игрока искусственным интеллектом.</p></div>`;
}

export function plainSummary(r){
 const summaries={
 'В ПРЕДЕЛАХ НОРМЫ':'В целом игрок показывает обычные результаты на своих героях. Бывают удачные и слабые игры, но по этой серии нет оснований говорить, что он постоянно подводит команду.',
 'НЕ В ФОРМЕ':'В последнее время игрок чаще выступает слабее ожидаемого. Важные для его роли показатели проседают в нескольких играх, поэтому дело не сводится к одному неудачному матчу.',
 'СКРЫТОПУЛЬНЫЙ':'В большинстве оценённых игр игрок заметно уступает обычным показателям своих героев. Слабые результаты повторяются, но по ним нельзя утверждать, что он специально мешает команде.',
 'ТАЩИТ':'В этой серии игрок часто показывает сильную игру: важные для его роли показатели заметно выше обычных. Даже если команда проигрывает, его личные результаты могут оставаться хорошими.',
 'НАДЁЖНЫЙ ТИММЕЙТ':'В целом игрок справляется со своей ролью лучше среднего ориентира. Отдельные слабые игры есть у всех — здесь они не перевешивают хорошие результаты.',
 'НЕСТАБИЛЬНЫЙ':'На одной и той же роли игрок заметно чередует сильные и слабые выступления. В одной игре получается многое, в другой показатели серьёзно проседают.',
 'СМЕШАННАЯ КАРТИНА':'Одни показатели говорят в пользу игрока, другие дают менее благоприятную картину. Поэтому сейчас нельзя уверенно назвать его игру сильной или слабой.',
 'НЕДОСТАТОЧНО ДАННЫХ':'Пока доступно слишком мало подходящих игр, чтобы уверенно судить об игроке. Ниже показано то, что уже удалось узнать.'};
 return summaries[r.verdict]||'Ниже разбираем, что у игрока получается и какие показатели проседают в доступных играх.';
}
